style.css:
@-moz-document domain("youtube.com") {
html, body {
    min-height: 100% !important;
    background-color: #10071c !important;
  }

  /* Imagem original enviada, incorporada sem filtros nem alterações */
  body {
    background-image: url("data:image/jpeg;base64,") !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* Deixa o fundo da interface transparente para a imagem aparecer */
  ytd-app,
  #content,
  #page-manager,
  ytd-browse,
  ytd-search,
  ytd-two-column-browse-results-renderer,
  ytd-watch-flexy,
  #primary,
  #secondary,
  ytd-rich-grid-renderer,
  ytd-rich-section-renderer,
  ytd-item-section-renderer,
  ytd-rich-item-renderer {
    background-color: transparent !important;
  }
}
